prompt:
¡Claro! Mira, necesito que me digas o código HTML dos últimos empregados, non sei si é unha boa idea incluír os datos nos campos de texto, pero é que así queda máis organizado.

<script>
  // Agrega el estilo para el campo de texto
  <style>
    .datos-emprego {
      width: 100%;
      padding: 10px;
      margin-bottom: 20px;
      border: 1px solid #ccc;
      border-radius: 5px;
    }
  </style>

  // Agrega el código HTML para los datos del empleado
  <div class="datos-emprego">
    <label for="nombre">Nome:</label>
    <input type="text" id="nombre" value="<?php echo $empleado->nombre; ?>">
  </div>

  <div class="datos-emprego">
    <label for="email">Correo electrónico:</label>
    <input type="email" id="email" value="<?php echo $empleado->email; ?>">
  </div>

  <div class="datos-emprego">
    <label for="departamento">Departamento:</label>
    <select id="departamento">
      <?php foreach ($departamentos as $departamento) { ?>
        <option value="<?php echo $departamento->id; ?>"><?php echo $departamento->nombre; ?></option>
      <?php } ?>
    </select>
  </div>

  // Agrega un botón para copiar el código
  <button onclick="copiarDatos()">Copiar datos</button>

  // Función para copiar el código en el portapapeles
  <script>
    function copiarDatos() {
      navigator.clipboard.writeText(`Nombre: ${document.getElementById('nombre').value}
Correo electrónico: ${document.getElementById('email').value}
Departamento: ${document.getElementById('departamento').value}`);
      alert('¡Los datos han sido copiados al portapapeles!');
    }
  </script>
</script>
